import XCTest

final class RunnerUITests: XCTestCase {
    func testOpenSettings() throws {
        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
        app.activate()

        let menuButton = app.buttons["User menu"]
        XCTAssertTrue(menuButton.waitForExistence(timeout: 20))
        menuButton.tap()
        Thread.sleep(forTimeInterval: 2)

        let dump = app.debugDescription
        try? dump.write(toFile: "/var/folders/vl/g_dyzwvs4_52rz0rdks_3j900000gp/T/opencode/hierarchy.txt", atomically: true, encoding: .utf8)

        let item = app.menuItems["User settings"]
        if item.waitForExistence(timeout: 5) {
            item.tap()
        } else if app.buttons["User settings"].waitForExistence(timeout: 3) {
            app.buttons["User settings"].tap()
        } else if app.cells["User settings"].waitForExistence(timeout: 3) {
            app.cells["User settings"].tap()
        } else if app.staticTexts["User settings"].waitForExistence(timeout: 3) {
            app.staticTexts["User settings"].tap()
        }

        XCTAssertTrue(app.navigationBars["Settings"].waitForExistence(timeout: 15))
    }
}

import XCTest

final class RunnerUITests: XCTestCase {
    func testOpenSettings() throws {
        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
        app.activate()
        Thread.sleep(forTimeInterval: 1)

        if !app.menuItems["User settings"].exists {
            let menuButton = app.buttons["User menu"]
            XCTAssertTrue(menuButton.waitForExistence(timeout: 20))
            menuButton.tap()
            Thread.sleep(forTimeInterval: 2)
        }

        let dump = app.debugDescription
        try? dump.write(toFile: "/var/folders/vl/g_dyzwvs4_52rz0rdks_3j900000gp/T/opencode/hierarchy.txt", atomically: true, encoding: .utf8)

        let item = app.menuItems["User settings"]
        if item.waitForExistence(timeout: 5) {
            item.tap()
        }

        XCTAssertTrue(app.navigationBars["Settings"].waitForExistence(timeout: 15))
    }
}
